INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(30401, 'Song of Songs 7:12', 'Song of Songs', 7, 12, 'راځه چې سحر وختى پاڅيږونه او د انګورو باغونو ته لاړ شونه چې د انګورو د ځيلو راټوکېدل ووينو او چې انارو ګلونه کړى دى کۀ نه، هلته به زۀ خپله مينه تا ته وښايمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30402, 'Song of Songs 7:13', 'Song of Songs', 7, 13, 'هلته به د مړه غونو بوټو خپله خوشبو راپرېښې وينه، او د ټولو نه ښې مېوې به زمونږ دروازې سره وينه، نوې او زاړۀ خوندونه، جانانه کوم چې ما ستا دپاره ساتلى دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30403, 'Genesis 44:30', 'Genesis', 44, 30, 'نو اوس که چېرې زه بېرته خپل پلار ته ورشم او هلک زمونږ سره نه وي، نو که زما پلار چې ژوند یې د هلک د ژوند سره تړلی دی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30404, 'Genesis 44:31', 'Genesis', 44, 31, 'وګوري چې هلک نشته هغه به مړ شي. هغه دومره زوړ دی چې هغه غم چې مونږ یې په هغه باندې راولو، هغه به ووژني.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30405, 'Joshua 6:8', 'Joshua', 6, 8, 'څنګه چې یوشع قوم ته وینا وکړه، هغه اووه کاهنان چې سرني یې وړل هغوی مخکې روان شول، خپل سرني یې وهل او د څښتن د لوظ صندوق د هغوی پسې ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30406, 'Joshua 6:9', 'Joshua', 6, 9, 'وسله وال ساتونکي د هغو کاهنانو په مخکې چې سرني یې وهل روان وو او شاتنۍ ساتونکې ډله د صندوق پسې روانه وه. په دې ټول وخت کې سرني وهل کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30407, 'Joshua 6:12', 'Joshua', 6, 12, 'یوشع سهار وختي پاڅېده او کاهنانو او خپلو کسانو ته یې هماغه امر وکړ. نو هغو کاهنانو چې د لوظ د صندوق د وړلو حکم ورته شوی ؤ هغه په خپلو اوږو باندې کېښود.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30408, 'Joshua 6:13', 'Joshua', 6, 13, 'بیا هغوی لکه د تېرې ورځې په شان په هماغه ترتیب سره د ښار ګردچاپېره وګرځېدل. لومړی هغه ساتونکي چې مخکې روان وو، بیا هغه کاهنان چې د ګرځېدلو په حال کې به یې هر وخت سرني وهل، ورپسې هغه کاهنان چې د څښتن د لوظ صندوق یې وړلو او په اخره کې شاتنۍ ساتونکې ډله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30409, 'Numbers 26:3', 'Numbers', 26, 3, 'په هغه وخت کې د اسراییلو ټول قوم د موآب په ډاګونو کې اریحا ته مخامخ د اردن د سیند په غاړه خېمې ودرولې وې. نو موسی او العازار کاهن د اسراییلو مشرانو ته د دې سرشمېرنې په اړه داسې لارښوونه وکړه:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30410, 'Numbers 26:4', 'Numbers', 26, 4, '«لکه څنګه چې څښتن موسی ته حکم کړی دی هغه ټول اسراییلیان چې عمر یې شل کاله یا زیات وي وشمارئ.» دا هغه اسراییلیان دي چې د مصر څخه راوتلي وو:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');